# %% ../../nbs/36_text.tokenizer.ipynb #dd56ed87
EOS_TOK = "<eos>"
BOS_TOK = "<bos>"
PAD_TOK = "<pad>"

def hf_tokenizer(name='gpt2'):
    "Pretrained Hugging Face tokenizer `name`, with `EOS_TOK`, `BOS_TOK` and `PAD_TOK` added as special tokens"
    tok = Tokenizer.from_pretrained(name)
    tok.add_special_tokens([EOS_TOK, BOS_TOK, PAD_TOK])
    return tok

# %% ../../nbs/36_text.tokenizer.ipynb #e6828c02
def id_dtype(tok):
    "The smallest type that holds every ID of `tok`"
    return np.uint16 if tok.get_vocab_size(with_added_tokens=True) <= 2**16 else np.uint32

# %% ../../nbs/36_text.tokenizer.ipynb #b9b7851c
def tokenize_batches(
    items, # Texts, or the items `get_texts` extracts them from
    tok, # HF `Tokenizer`
    get_texts=None, # Column of texts, or function from a batch of `items` to its texts
    bs=1024, # Texts per tokenizer batch
):
    "Encode each `bs` texts into an Arrow list array, where document `i` is `values[offsets[i]:offsets[i+1]]`"
    if isinstance(get_texts, str): get_texts = itemgetter(get_texts)
    dtype = id_dtype(tok)
    for i in progress_bar(range(0, len(items), bs)):
        batch = items[i:i+bs]
        ids = [np.asarray(e.ids, dtype=dtype) for e in tok.encode_batch_fast(list(batch if get_texts is None else get_texts(batch)))]
        yield pa.LargeListArray.from_arrays(np.cumsum([0] + [len(o) for o in ids]), np.concatenate(ids))

@delegates(tokenize_batches)
def tokenize_texts(items, tok, **kwargs):
    "Encode texts into an Arrow column with one list of token IDs per document"
    return pa.chunked_array(list(tokenize_batches(items, tok, **kwargs)), type=pa.large_list(pa.from_numpy_dtype(id_dtype(tok))))


