class TokenDocs:
    "Document views backed by an Arrow list column of token IDs"
    def __init__(
        self,
        ids # Arrow list array or chunked array with one list of token IDs per document
    ):
        self.ids = ids
        chunks = ids.chunks if isinstance(ids, pa.ChunkedArray) else [ids]
        self.chunks = [(c.values.to_numpy(), c.offsets.to_numpy()) for c in chunks]
        self.starts = np.cumsum([0] + [len(c) for c in chunks]).tolist()
        self.lens = np.concatenate([np.diff(o) for _,o in self.chunks]) if chunks else np.empty(0, dtype=np.int64)
        self.idxs = np.arange(self.starts[-1])

    def __len__(self): return len(self.idxs)
    def __repr__(self): return f'TokenDocs({len(self)} documents)'
    @property
    def iloc(self): return self

    def __getitem__(self, i):
        i = self.idxs[i]
        if not is_indexer(i): # subset view (e.g. train/val splits) sharing the same token arrays
            res = copy(self)
            res.idxs = i
            return res
        c = bisect_right(self.starts, i)-1
        flat, offsets = self.chunks[c]
        i -= self.starts[c]
        return flat[offsets[i]:offsets[i+1]]

# %% ../../nbs/36_text.tokenizer.ipynb #46926f4a
def save_token_cache(
    path, # Arrow file to write
    ids, # Arrow list arrays of token IDs, such as the batches from `tokenize_batches`
    tok, # Tokenizer that produced `ids`
    xtra, # DataFrame of per-document columns (e.g. labels, file paths, splits)
):
    "Save token IDs, `xtra` columns and the tokenizer to the Arrow file `path`"
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    meta = pa.Table.from_pandas(xtra, preserve_index=False).combine_chunks()
    schema = pa.schema([pa.field('ids', pa.large_list(pa.from_numpy_dtype(id_dtype(tok)))), *meta.schema],
        metadata=dict(tokenizer=tok.to_str()))
    tmp, n = path.with_suffix('.tmp'), 0
    try:
        with pa.ipc.new_file(tmp, schema) as w:
            for a in (ids.chunks if isinstance(ids, pa.ChunkedArray) else ids):
                rows = meta.slice(n, len(a))
                if len(rows) != len(a): raise ValueError('xtra must have one row per document')
                w.write_batch(pa.RecordBatch.from_arrays([a, *(c.chunk(0) for c in rows.columns)], schema=schema))
                n += len(a)
        if n != len(xtra): raise ValueError('xtra must have one row per document')
        tmp.replace(path)
    except Exception:
        tmp.unlink(missing_ok=True)
        raise

# %% ../../nbs/36_text.tokenizer.ipynb #33413cd5
def load_token_cache(path):
    "Memory-map one or more Arrow caches, returning their documents, tokenizer and `xtra` columns"
    tbl = pa.concat_tables([pa.ipc.open_file(pa.memory_map(str(p))).read_all() for p in L(path)], promote_options='default')
    tok = Tokenizer.from_str(tbl.schema.metadata[b'tokenizer'].decode())
    return TokenDocs(tbl['ids']), tok, tbl.drop_columns('ids').to_pandas()

# %% ../../nbs/36_text.tokenizer.ipynb #6d97eaf8
def get_dataset_data(
    name, # Hugging Face Hub dataset name or local dataset directory
    split, # Split name or expression, such as `'train'` or `'train[:1%]'`
    get_data=None, # Optional callable returning (texts, xtra DataFrame) for the split
    subset=None, # Dataset configuration name
    text_col=None, # Text column; required when get_data is not supplied
    xtra_cols=(), # Columns to cache alongside the source split
):
    "Load one dataset split and prepare its texts and `xtra` columns"
    if get_data is None and text_col is None: raise ValueError('Provide text_col or get_data')
    ds = load_dataset(name, subset, split=split)
    if get_data is None: texts, xtra = ds[text_col], pd.DataFrame({c: ds[c] for c in xtra_cols}, index=range(len(ds)))
    else: texts, xtra = get_data(ds)
    return texts, xtra.assign(split=split)


# %% ../../nbs/36_text.tokenizer.ipynb #28842e1f
@delegates(get_dataset_data)
def tokenize_dataset(
    name, # Hugging Face Hub dataset name or local dataset directory
    subset=None, # Dataset configuration name
    split=None, # All splits if None, or a split name/expression or list of them
    tok='gpt2', # Tokenizer name for `hf_tokenizer`
    cache_dir=None, # Cache directory; defaults to a path keyed by source and tokenizer
    bs=1024, # Texts per tokenizer batch
    **kwargs
):
    "Build or load one Arrow token cache per split of a Hugging Face Hub dataset or local dataset directory"
    cache_dir = Path(cache_dir or fastai_path('data')/'token_cache'/str(name).lstrip('/')/(subset or 'default')/tok)
    if split is None: split = get_dataset_split_names(name, subset)
    paths = [cache_dir/f'{s}.arrow' for s in L(split)]
    tokenizer = None
    for s,path in zip(L(split), paths):
        if path.exists(): continue
        texts, xtra = get_dataset_data(name, s, subset=subset, **kwargs)
        if tokenizer is None: tokenizer = hf_tokenizer(tok)
        save_token_cache(path, tokenize_batches(texts, tokenizer, bs=bs), tokenizer, xtra)
    return load_token_cache(paths)

# %% ../../nbs/36_text.tokenizer.ipynb #18238162
def get_folder_data(
    path, # Folder of text files
    get_xtra=None # Callable returning `xtra` columns for nonstandard folder layouts
):
    "List sorted text files under `path` and prepare their `xtra` columns"
    path = Path(path)
    files = get_text_files(path).sorted()
    rel_files = [f.relative_to(path) for f in files]
    paths = [str(f) for f in rel_files]
    if get_xtra is None:
        labels = [f.parent.name if len(f.parts) >= 2 else None for f in rel_files]
        splits = [f.parents[1].name if len(f.parts) >= 3 else None for f in rel_files]
        xtra = pd.DataFrame(dict(path=paths, label=labels, split=splits))
    else:
        xtra = get_xtra(rel_files)
        if len(xtra) != len(files): raise ValueError('get_xtra must return one row per file')
        xtra = pd.concat([pd.DataFrame(dict(path=paths)), xtra.reset_index(drop=True)], axis=1)
    return files, xtra

