@delegates(tokenize_batches, but=['get_texts'])
def tokenize_folder(
    path, # Folder of text files
    tok='gpt2', # Tokenizer name for `hf_tokenizer`
    get_xtra=None, # Callable returning `xtra` columns for nonstandard folder layouts
    cache_dir=None, # Cache directory; defaults to a path keyed by the folder's full path and tokenizer
    **kwargs
):
    "Cache the text files under `path` in one Arrow file, with their paths and `xtra` columns"
    path = Path(path)
    files, xtra = get_folder_data(path, get_xtra)
    if cache_dir is None: cache_dir = fastai_path('data')/'token_cache'/str(path.resolve()).lstrip('/')/tok
    cache = Path(cache_dir)/'files.arrow'
    if cache.exists():
        docs, tokenizer, cached = load_token_cache(cache)
        if cached['path'].tolist() == xtra['path'].tolist(): return files, docs, tokenizer, xtra
    tokenizer = hf_tokenizer(tok)
    ids = tokenize_batches(files, tokenizer, get_texts=lambda fs: [f.read_text(encoding='utf-8') for f in fs], **kwargs)
    save_token_cache(cache, ids, tokenizer, xtra)
    return files, load_token_cache(cache)[0], tokenizer, xtra


# %% ../../nbs/36_text.tokenizer.ipynb #80b93f00
class HfTokenizer(Transform):
    "Encode texts or cached token IDs with `tok`, adding `BOS_TOK` and `EOS_TOK`, and decode them back to text"
    input_types = (str, np.ndarray)
    def __init__(self, tok):
        self.tok = tok
        self.bos,self.eos,self.pad_id = (tok.token_to_id(t) for t in (BOS_TOK, EOS_TOK, PAD_TOK))
        self.vocab = [tok.id_to_token(i) for i in range(tok.get_vocab_size())]
    def _add_boundaries(self, ids): return TensorText([self.bos] + ids + [self.eos])
    def _len(self, o): return len(o) if isinstance(o, np.ndarray) else len(self.tok.encode(o).ids)
    def get_lengths(self, items):
        if isinstance(items, TokenDocs): return (items.lens+2)[items.idxs]
        items = L(items)
        if not items: return L()
        return L(self._len(o)+2 for o in items) if isinstance(items[0], (np.ndarray, str)) else None
    def encodes(self, s:str): return self._add_boundaries(self.tok.encode(s).ids)
    def encodes(self, s:np.ndarray): return self._add_boundaries(s.tolist())
    def decodes(self, t:TensorText): return TitledStr(self.tok.decode(t.tolist(), skip_special_tokens=False))

# %% ../../nbs/36_text.tokenizer.ipynb #74e5552c
class Reverse(Transform):
    "Reverse a token sequence on encode and restore its original order on decode"
    def encodes(self, o): return o.flip(0)
    def decodes(self, o): return o.flip(0)


