class HfTextBlock(TransformBlock):
    "A `TransformBlock` for documents that `tok_tfm` encodes straight to token ids"
    def __init__(
        self,
        tok_tfm, # Tokenizing `Transform`, such as `HfTokenizer`
        is_lm=False, # Build a language model loader instead of a classifier loader
        seq_len=72, # Language model sequence length or classifier padding chunk size
        backwards=False # Reverse each tokenized document
    ):
        type_tfms = [tok_tfm] + ([Reverse()] if backwards else [])
        dls_kwargs = {'seq_len': seq_len} if is_lm else {'before_batch': Pad_Chunk(seq_len=seq_len, pad_idx=tok_tfm.pad_id)}
        super().__init__(type_tfms=type_tfms, dl_type=LMDataLoader if is_lm else SortedDL, dls_kwargs=dls_kwargs)

# %% ../../nbs/36_text.tokenizer.ipynb #cb7e9f3d
def get_splits(
    xtra, # Cached `xtra` columns, one row per document
    train='train', # Training split name
    valid='validation', # Validation split name
    valid_pct=None, # Random validation fraction; None uses named source splits
    seed=None, # Random split seed
    folders=None # Top-level source folders to include; valid_pct splits all their rows
):
    "Training and validation row positions from cached `xtra` columns"
    rows = L(range_of(xtra))
    if folders is not None:
        folders = L(folders)
        rows = L(mask2idxs(xtra['path'].map(lambda p: Path(p).parts[0] in folders)))
        xtra = xtra.iloc[rows]
    if valid_pct is not None:
        train_idx, valid_idx = RandomSplitter(valid_pct, seed=seed)(rows)
        return rows[train_idx], rows[valid_idx]
    return [rows[mask2idxs(xtra['split'] == name)] for name in (train, valid)]

# %% ../../nbs/36_text.tokenizer.ipynb #e105258d
class TextDataLoadersNew(DataLoaders):
    "Wrapper around several `DataLoader`s with factory methods for texts encoded by `HfTokenizer`"
    @classmethod
    @delegates(Datasets.dataloaders)
    def from_docs(
        cls,
        docs, # `TokenDocs` to load
        tok, # Tokenizer used to encode the documents
        splits, # Training and validation document indices
        labels=None, # One label per document; None for a language model
        seq_len=72, # Language model sequence length or classifier padding chunk size
        backwards=False, # Reverse each tokenized document
        bs=64, # DataLoader batch size
        **kwargs
    ):
        "Build language model or classification loaders from tokenized documents"
        is_lm = labels is None
        text = HfTextBlock(HfTokenizer(tok), is_lm=is_lm, seq_len=seq_len, backwards=backwards)
        tls = [TfmdLists(docs, text.type_tfms, splits=splits)]
        if not is_lm: tls.append(TfmdLists(labels, CategoryBlock().type_tfms, splits=splits))
        dsets = Datasets(tls=tls, dl_type=text.dl_type)
        kwargs = {**text.dls_kwargs, 'after_item': text.item_tfms, 'after_batch': text.batch_tfms, **kwargs}
        return dsets.dataloaders(bs=bs, **kwargs)

# %% ../../nbs/36_text.tokenizer.ipynb #6485f72d
@patch(cls_method=True)
@delegates(TextDataLoadersNew.from_docs, but=['labels'])
def from_dataset(
    cls:TextDataLoadersNew,
    name, # Hub dataset name or local dataset directory
    train='train', # Source split used for training
    valid='validation', # Source split used for validation
    valid_pct=None, # Random validation fraction of selected rows; None uses source splits
    seed=None, # Random split seed
    tok='gpt2', # Tokenizer name for `hf_tokenizer`
    cache_dir=None, # Token cache directory
    label_col=None, # Label column in the cached `xtra`; None for a language model
    xtra_cols=(), # Additional source columns to cache; `label_col` is included automatically
    subset=None, # Dataset configuration name
    text_col=None, # Text column; required when `get_data` is not supplied
    get_data=None, # Callable returning texts and `xtra` for each source split
    **kwargs
):
    "Build language model or classification loaders using cached `xtra` columns"
    xtra_cols = (L(xtra_cols) + L(label_col)).unique()
    split = [train, valid] if valid_pct is None else None
    docs, tok, xtra = tokenize_dataset(name, subset=subset, split=split, tok=tok,
        cache_dir=cache_dir, text_col=text_col, get_data=get_data, xtra_cols=xtra_cols)
    splits = get_splits(xtra, train=train, valid=valid, valid_pct=valid_pct, seed=seed)
    labels = None if label_col is None else xtra[label_col]
    return cls.from_docs(docs, tok, splits, labels=labels, **kwargs)

