@patch(cls_method=True)
@delegates(TextDataLoadersNew.from_docs, but=['labels'])
def from_folder(
    cls:TextDataLoadersNew,
    path, # Folder of text files
    train='train', # Training split name in the cached `split` column
    valid='valid', # Validation split name in the cached `split` column
    valid_pct=None, # Random validation fraction; None uses source splits
    seed=None, # Random split seed
    is_lm=False, # Build a language model instead of a classifier
    tok='gpt2', # Tokenizer name for `hf_tokenizer`
    folders=None, # Source folders to include; with `valid_pct`, combine their rows before splitting
    cache_dir=None, # Token cache directory
    label_col='label', # Cached label column for classification
    get_xtra=None, # Callable returning `xtra` columns for nonstandard folder layouts
    **kwargs
):
    "Build language model or classification loaders from a folder's cached `xtra` columns"
    _, docs, tok, xtra = tokenize_folder(path, tok, get_xtra=get_xtra, cache_dir=cache_dir)
    splits = get_splits(xtra, train=train, valid=valid, valid_pct=valid_pct, seed=seed, folders=folders)
    labels = None if is_lm else xtra[label_col]
    return cls.from_docs(docs, tok, splits, labels=labels, path=path, **kwargs)
